import json

def main():
    with open('/root/.gemini/tmp/all_usgs_data.json', 'r') as f:
        all_batches = json.load(f)

    station_max_gh = {}

    for batch in all_batches:
        if 'value' not in batch or 'timeSeries' not in batch['value']:
            continue

        for ts in batch['value']['timeSeries']:
            station_id = ts['sourceInfo']['siteCode'][0]['value']
            param_cd = ts['variable']['variableCode'][0]['value']

            # 00065 is Gage Height
            if param_cd == '00065':
                values = ts['values'][0]['value']
                gh_values = [float(v['value']) for v in values if v['value'] != '-999999']
                if gh_values:
                    max_gh = max(gh_values)
                    station_max_gh[station_id] = max(station_max_gh.get(station_id, 0), max_gh)

    # Print stations and their max gage height
    sorted_stations = sorted(station_max_gh.items(), key=lambda x: x[1], reverse=True)
    for sid, gh in sorted_stations:
        print(f"{sid}: {gh}")

if __name__ == "__main__":
    main()

import json

def main():
    try:
        with open('/root/.gemini/tmp/all_usgs_iv_data.json', 'r') as f:
            all_batches = json.load(f)
    except Exception as e:
        print(f"Error reading file: {e}")
        return

    station_max_gh = {}

    for batch in all_batches:
        if 'value' not in batch or 'timeSeries' not in batch['value']:
            continue

        for ts in batch['value']['timeSeries']:
            station_id = ts['sourceInfo']['siteCode'][0]['value']
            # There might be multiple time series for 00065 with different methods
            values = ts['values'][0]['value']
            gh_values = [float(v['value']) for v in values if v['value'] != '-999999']
            if gh_values:
                max_gh = max(gh_values)
                if station_id not in station_max_gh or max_gh > station_max_gh[station_id]:
                    station_max_gh[station_id] = max_gh

    sorted_stations = sorted(station_max_gh.items(), key=lambda x: x[1], reverse=True)
    for sid, gh in sorted_stations:
        print(f"{sid}: {gh}")

if __name__ == "__main__":
    main()

